import unittest
from typing import List

from hourglass.rounding import round_span_labels
from hourglass.parsing import parse_span

def _labels(text: str, step: int) -> List[str]:
    return round_span_labels([parse_span(text)], step)

class RoundSpanLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        labels = _labels("09:04-17:12", 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        labels = _labels("09:01-09:03", 2)
        self.assertEqual(labels, ["09:02-09:04 (0h 2m)"])

    def test_half_hour_step_rounds_up(self):
        labels = _labels("09:30-10:30", 60)
        self.assertEqual(labels, ["10:00-11:00 (1h 0m)"])

    def test_end_of_day(self):
        labels = _labels("22:50-24:00", 15)
        self.assertEqual(labels, ["22:45-24:00 (1h 15m)"])

    def test_collapsed_span_keeps_zero_label(self):
        labels = _labels("09:01-09:04", 15)
        self.assertEqual(labels, ["09:00-09:00 (0h 0m)"])

    def test_order_follows_input(self):
        texts = ["13:00-14:00", "08:00-09:00"]
        labels = round_span_labels(
            map(parse_span, texts), 60
        )
        self.assertEqual(labels[0], "13:00-14:00 (1h 0m)")
        self.assertEqual(labels[1], "08:00-09:00 (1h 0m)")

    def test_empty_input(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    _labels("09:00-10:00", step)
